public static <T extends Enum<T>> Optional<T> fromString(Class<T> enumClass, String name) {
    if (name == null || name.isBlank()) return Optional.empty();
    try {
        return Optional.of(Enum.valueOf(enumClass, name.trim().toUpperCase()));
    } catch (IllegalArgumentException e) {
        return Optional.empty();
    }
}
// Usage:
Optional<Day> day = fromString(Day.class, userInput);
day.ifPresent(d -> System.out.println('Valid day: ' + d));
// OR for fast lookup, build a Map once: Map<String, Day> LOOKUP = Arrays.stream(Day.values()).collect(Collectors.toMap(Day::name, d -> d));

