public enum TrafficLight {
    RED(60) {
        @Override public TrafficLight next() { return GREEN; }
    },
    GREEN(45) {
        @Override public TrafficLight next() { return YELLOW; }
    },
    YELLOW(5) {
        @Override public TrafficLight next() { return RED; }
    };

    private final int durationSeconds;

    TrafficLight(int durationSeconds) {
        if (durationSeconds <= 0) throw new IllegalArgumentException('Duration must be positive');
        this.durationSeconds = durationSeconds;
    }

    public int getDurationSeconds() { return durationSeconds; }
    public abstract TrafficLight next();
}
// Usage: TrafficLight current = TrafficLight.RED;
// current.getDurationSeconds() → 60, current.next() → GREEN

